// META_ANALYSIS_v1 (v0.4) - extraction des effets (LLM) + pooling inverse-variance
// fixe + aleatoire (DerSimonian-Laird), heterogeneite Q/I2/tau2, intervalle de prediction,
// test d'Egger, forest plot + funnel plot (SVG). Mesures: OR/RR/HR (log) et MD/SMD (lineaire).
const PROXY = 'http://host.docker.internal:3456';
const items = $input.all();
const articles = items.map(i => i.json);
const a0 = articles[0] || {};
const OUTCOME = (a0._meta_outcome || a0.question || '').toString();
let MEASURE = (a0._meta_measure || 'auto').toString().toUpperCase();
// J2 : ajustement de Hartung-Knapp-Sidik-Jonkman - OPTION, DESACTIVEE PAR DEFAUT.
// L IC du modele aleatoire (DerSimonian-Laird) est calcule avec le quantile normal 1,96 :
// a petit nombre d etudes ou en presence de forte heterogeneite il est trop etroit (le taux
// d erreur reel depasse largement les 5% annonces). L option remplace ce quantile par un t
// a k-1 ddl et repondere l erreur type. Elle CHANGE des chiffres publiables : elle doit donc
// etre demandee explicitement (_meta_hksj sur articles[0]), et la methode retenue est nommee
// dans le resume (summary.random_ci_method) pour qu un ecart entre deux versions reste
// explicable. Sans l option, les chiffres sont strictement ceux des versions precedentes.
function _truthyUL(v){ return /^(1|true|on|oui|yes)$/i.test(String(v==null?'':v).trim()); }
const HKSJ = _truthyUL(a0._meta_hksj);
const LOGM = { OR:1, RR:1, HR:1 };
console.log('[Meta] ' + articles.length + ' articles, mesure=' + MEASURE);

function extractJson(raw){ if(!raw) return null; let s=String(raw).replace(/```json/gi,'').replace(/```/g,''); const i=s.indexOf('{'),j=s.lastIndexOf('}'); if(i<0||j<=i) return null; const f=s.substring(i,j+1); try{return JSON.parse(f);}catch(e){} try{return JSON.parse(f.replace(/,\s*([}\]])/g,'$1'));}catch(e){} return null; }
function num(x){ const v=parseFloat(x); return isFinite(v)?v:null; }

// ===== J1 : quantile de Student bilateral 95% (pur JS, AUCUNE dependance) =====
// L intervalle de PREDICTION (Higgins, Thompson & Spiegelhalter 2009) est
//   mu_hat +/- t(k-2 ; 0,975) * sqrt(tau2 + var(mu_hat))
// et NON +/- 1,96 : avec 3 a 5 etudes t vaut 3,18 a 12,71 et l intervalle en 1,96 est
// faussement etroit (precision mensongere). CDF de Student via la beta incomplete reguliere
// (fraction continue de Lentz) puis inversion par dichotomie.
// MIROIR EXACT de app/src/lib/metaCalc.ts (memes constantes, memes iterations, memes arrondis).
function _lgammaUL(x){
  var g=[676.5203681218851,-1259.1392167224028,771.32342877765313,-176.61502916214059,12.507343278686905,-0.13857109526572012,9.9843695780195716e-6,1.5056327351493116e-7];
  if (x<0.5) return Math.log(Math.PI/Math.sin(Math.PI*x))-_lgammaUL(1-x);
  var y=x-1, a=0.99999999999980993, t=y+7.5;
  for (var i=0;i<8;i++) a+=g[i]/(y+i+1);
  return 0.5*Math.log(2*Math.PI)+(y+0.5)*Math.log(t)-t+Math.log(a);
}
function _betacfUL(a,b,x){
  var MAXIT=300, EPS=3e-14, FPMIN=1e-300;
  var qab=a+b, qap=a+1, qam=a-1;
  var c=1, d=1-qab*x/qap;
  if (Math.abs(d)<FPMIN) d=FPMIN;
  d=1/d; var h=d;
  for (var m=1;m<=MAXIT;m++){
    var m2=2*m;
    var aa=m*(b-m)*x/((qam+m2)*(a+m2));
    d=1+aa*d; if (Math.abs(d)<FPMIN) d=FPMIN;
    c=1+aa/c; if (Math.abs(c)<FPMIN) c=FPMIN;
    d=1/d; h*=d*c;
    aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2));
    d=1+aa*d; if (Math.abs(d)<FPMIN) d=FPMIN;
    c=1+aa/c; if (Math.abs(c)<FPMIN) c=FPMIN;
    d=1/d; var del=d*c; h*=del;
    if (Math.abs(del-1)<EPS) break;
  }
  return h;
}
function _ibetaUL(a,b,x){
  if (x<=0) return 0;
  if (x>=1) return 1;
  var bt=Math.exp(_lgammaUL(a+b)-_lgammaUL(a)-_lgammaUL(b)+a*Math.log(x)+b*Math.log(1-x));
  if (x < (a+1)/(a+b+2)) return bt*_betacfUL(a,b,x)/a;
  return 1-bt*_betacfUL(b,a,1-x)/b;
}
function _tcdfUL(t,df){
  var p=0.5*_ibetaUL(df/2,0.5,df/(df+t*t));
  return (t>0)?(1-p):p;
}
// t tel que P(T<=t)=0,975 pour df ddl. Renvoie null si df<1 (pas d intervalle de prediction).
function tQuantile975(df){
  if (!(df>=1)) return null;
  var lo=0, hi=1000;
  for (var i=0;i<200;i++){ var mid=0.5*(lo+hi); if (_tcdfUL(mid,df)<0.975) lo=mid; else hi=mid; }
  return 0.5*(lo+hi);
}
const PI_METHOD = 'Higgins, Thompson & Spiegelhalter : quantile de Student a k-2 ddl (bilateral 95%)';
// J2 : libelles des methodes d IC du modele aleatoire. Chaines IDENTIQUES cote interface
// (app/src/lib/metaCalc.ts) : le nom de la methode voyage avec les chiffres.
const RANDOM_CI_METHOD_DL = 'DerSimonian-Laird : intervalle de confiance par quantile normal 1,96 (methode par defaut)';
const RANDOM_CI_METHOD_HKSJ = 'DerSimonian-Laird + ajustement de Hartung-Knapp-Sidik-Jonkman : erreur type reponderee et quantile de Student a k-1 ddl (option activee)';
const HKSJ_NOTE_K = 'ajustement non applicable : il faut au moins 2 etudes (ddl = k-1 >= 1)';
const HKSJ_NOTE_Q = 'ajustement non applicable : dispersion nulle entre les etudes (q = 0), il donnerait un intervalle de largeur nulle';
const HKSJ_NOTE_NARROW = 'attention : ici l ajustement RESSERRE l intervalle (q < 1, etudes tres concordantes) au lieu de l elargir';
// q = somme(w* (yi - mu)^2) / (k-1) ; var_HK = q / somme(w*) ; IC = mu +/- t(k-1 ; 0,975) * sqrt(var_HK).
// Deux cas degeneres traites explicitement : k < 2 (ddl = k-1 = 0, division par zero) et q = 0
// (etudes strictement concordantes : l IC serait de largeur nulle, precision mensongere).
// Dans ces deux cas l ajustement N EST PAS applique et l IC reste celui de DerSimonian-Laird.
function hksjStats(yis, wstars, sumWs, mu){
  var kk=yis.length, dfHK=kk-1;
  if (!(kk>=2)) return { available:false, df:dfHK, t:null, se:null, q:null, note:HKSJ_NOTE_K };
  var sHK=0;
  for (var i=0;i<kk;i++){ sHK+=wstars[i]*Math.pow(yis[i]-mu,2); }
  var qHK=sHK/(kk-1);
  var varHK=qHK/sumWs;
  var seHK=Math.sqrt(varHK);
  var tHK=tQuantile975(dfHK);
  if (!isFinite(seHK) || !(seHK>0) || tHK==null)
    return { available:false, df:dfHK, t:null, se:null, q:isFinite(qHK)?qHK:null, note:HKSJ_NOTE_Q };
  return { available:true, df:dfHK, t:tHK, se:seHK, q:qHK };
}
const ZERO_METHOD = 'correction de continuite 0,5 sur les zeros simples ; etudes a double zero exclues du poolage des rapports (Cochrane Handbook 10.4.4.1)';

// PONT EXTRACTION -> META (interactivite 0.4.3) : reutilise des donnees chiffrees deja
// disponibles (module Extraction preset "meta-ready", cle=schema meta ; OU _meta_data
// precalcule/verifie par l'humain) plutot que de relancer un appel LLM. Rend null si rien
// d'exploitable -> extraction LLM classique (retro-compatible).
function reuseExisting(art){
  var md = art._meta_data;
  if (md && typeof md==='object' && md.data_type && md.data_type!=='none') return md;
  var ex = art._extracted; if (!ex || typeof ex!=='object') return null;
  var ei=num(ex.events_intervention), ni=num(ex.n_intervention), ec=num(ex.events_control), nc=num(ex.n_control);
  var mi=num(ex.mean_intervention), si=num(ex.sd_intervention), mc=num(ex.mean_control), sc=num(ex.sd_control);
  var eff=num(ex.effect), lo=num(ex.ci_lower), hi=num(ex.ci_upper);
  var base = { outcome: ((ex.outcome!=null?ex.outcome:(art._meta_outcome||''))+''), design: ((ex.design||'')+'').toLowerCase()||undefined, _reused:true };
  if (ei!=null && ni!=null && ec!=null && nc!=null)
    return Object.assign(base, { data_type:'binary', events_intervention:ei, n_intervention:ni, events_control:ec, n_control:nc });
  if (mi!=null && si!=null && ni!=null && mc!=null && sc!=null && nc!=null)
    return Object.assign(base, { data_type:'continuous', mean_intervention:mi, sd_intervention:si, n_intervention:ni, mean_control:mc, sd_control:sc, n_control:nc });
  if (eff!=null && lo!=null && hi!=null)
    return Object.assign(base, { data_type:'precomputed', effect_measure:((ex.effect_measure||'')+'').toUpperCase()||undefined, effect:eff, ci_lower:lo, ci_upper:hi });
  return null;
}

function buildPrompt(a, text){
  return [
    'Extract the quantitative result for the MAIN outcome of this study, for a meta-analysis.',
    OUTCOME ? ('TARGET OUTCOME (focus on this if present): ' + OUTCOME.substring(0,200)) : '',
    '',
    'TITLE: ' + ((a.title||'').substring(0,200)),
    'TEXT: ' + (text||'').toString().substring(0,8000),
    '',
    'Return STRICT JSON ONLY:',
    '{',
    '  "outcome": "<short outcome name>",',
    '  "design": "rct" | "nonrandomized",',
    '  "data_type": "binary" | "continuous" | "precomputed" | "proportion" | "none",',
    '  ("proportion" = single-arm prevalence/incidence: fill events_intervention + n_intervention only),',
    '  "events_intervention": <int|null>, "n_intervention": <int|null>,',
    '  "events_control": <int|null>, "n_control": <int|null>,',
    '  "mean_intervention": <num|null>, "sd_intervention": <num|null>,',
    '  "mean_control": <num|null>, "sd_control": <num|null>,',
    '  "effect_measure": "OR"|"RR"|"HR"|"MD"|"SMD"|null, "effect": <num|null>, "ci_lower": <num|null>, "ci_upper": <num|null>',
    '}',
    'Use "none" if no usable quantitative result is reported. Numbers only (no text, no %).'
  ].filter(Boolean).join('\n');
}

// derive yi (effect, log space si ratio) + vi pour la mesure demandee
function deriveEffect(d, measure){
  const isLog = !!LOGM[measure];
  // LOT-A F7 : proportions single-arm (PFT) - yi = double arcsinus Freeman-Tukey, vi = 1/(4n+2)
  if (measure==='PFT'){
    const x=num(d.events_intervention), nn=num(d.n_intervention);
    if (x!=null && nn!=null && nn>0 && x>=0 && x<=nn){
      const yi=0.5*(Math.asin(Math.sqrt(x/(nn+1)))+Math.asin(Math.sqrt((x+1)/(nn+1))));
      return {yi:yi, vi:1/(4*nn+2)};
    }
    return null;
  }
  // binary -> OR / RR (donnees brutes prioritaires si presentes)
  if ((measure==='OR'||measure==='RR')){
    let a=num(d.events_intervention), n1=num(d.n_intervention), c=num(d.events_control), n2=num(d.n_control);
    if (a!=null&&n1!=null&&c!=null&&n2!=null&&n1>0&&n2>0){
      let b=n1-a, dd=n2-c;
      // J6 (Cochrane Handbook 10.4.4.1) : une etude SANS AUCUN evenement dans les deux bras
      // n apporte aucune information sur un rapport (OR/RR). Lui appliquer la correction 0,5
      // lui fabrique un OR artificiel proche de 1 qui tire le resultat groupe vers l absence
      // d effet -> elle est EXCLUE du poolage (mais comptee et signalee dans le resume).
      if (a<=0 && c<=0){ return {exclude:'double_zero'}; }
      var cc=false;
      if (a<=0||b<=0||c<=0||dd<=0){ a+=0.5;b+=0.5;c+=0.5;dd+=0.5; cc=true; }
      if (measure==='OR'){ const yi=Math.log((a*dd)/(b*c)); const vi=1/a+1/b+1/c+1/dd; return {yi:yi,vi:vi,cc:cc}; }
      const r1=a/(a+b), r2=c/(c+dd); const yi=Math.log(r1/r2); const vi=1/a-1/(a+b)+1/c-1/(c+dd); return {yi:yi,vi:vi,cc:cc};
    }
  }
  // continuous -> MD / SMD (donnees brutes)
  if ((measure==='MD'||measure==='SMD')){
    const m1=num(d.mean_intervention), s1=num(d.sd_intervention), n1=num(d.n_intervention);
    const m2=num(d.mean_control), s2=num(d.sd_control), n2=num(d.n_control);
    if (![m1,s1,n1,m2,s2,n2].some(function(x){return x==null;}) && n1>0 && n2>0 && s1>=0 && s2>=0){
      if (measure==='MD'){ const yi=m1-m2; const vi=(s1*s1)/n1+(s2*s2)/n2; return {yi:yi,vi:vi}; }
      const sp=Math.sqrt(((n1-1)*s1*s1+(n2-1)*s2*s2)/(n1+n2-2));
      if (sp>0){ const dd=(m1-m2)/sp; const J=1-3/(4*(n1+n2)-9); const g=J*dd; const vi=(n1+n2)/(n1*n2)+g*g/(2*(n1+n2)); return {yi:g,vi:vi}; }
    }
  }
  // effet + IC pre-calcules (fallback, quel que soit data_type)
  if (d.effect!=null && d.ci_lower!=null && d.ci_upper!=null){
    const em=(d.effect_measure||measure||'').toUpperCase();
    const pl=!!LOGM[em];
    if (em && em!==measure) return null; // mesure incompatible
    let eff=num(d.effect), lo=num(d.ci_lower), hi=num(d.ci_upper);
    if (eff==null||lo==null||hi==null||hi<=lo) return null;
    if (pl){ if(eff<=0||lo<=0||hi<=0) return null; const yi=Math.log(eff), se=(Math.log(hi)-Math.log(lo))/(2*1.96); return {yi:yi,vi:se*se}; }
    const yi=eff, se=(hi-lo)/(2*1.96); return {yi:yi,vi:se*se};
  }
  return null;
}

// ---- 1. Extraction LLM par article ----
const studies = [];
for (let i=0;i<articles.length;i++){
  const art = articles[i];
  // STUDY_GROUPS_v1 (F3 v2) : companion papers - un seul rapport par ETUDE entre dans le pool
  // (unite d'analyse Cochrane = l'etude). Le regroupement est pose par /api/study-groups
  // (bouton Appliquer du chargeur de corpus) : les rapports non-primaires sont ecartes ici.
  if (art._study_group && art._study_group_primary === false){
    art._meta_status = 'companion_skipped';
    art._meta_included = false;
    art._meta_note = 'rapport secondaire du groupe ' + art._study_group + ' - seul le rapport principal est poole';
    continue;
  }
  // PONT : donnees deja extraites/verifiees -> on saute l'appel LLM (economie + tracabilite)
  const __reused = reuseExisting(art);
  if (__reused){ art._meta_data = __reused; art._meta_status='extracted'; art._meta_basis='reused'; studies.push(art); continue; }
  // Texte : PDF integral si dispo (les chiffres sont souvent dans les tableaux/resultats), sinon abstract
  let basis='abstract', text='';
  const pdf = art.pdf_local || '';
  if (pdf){ try { const resp=await this.helpers.httpRequest({ method:'POST', url:PROXY+'/extract-pdf', body:JSON.stringify({ pdf_path:pdf, max_chars:24000, skip_biblio:true }), headers:{'Content-Type':'application/json'}, json:true, timeout:60000 }); if(resp&&resp.success&&resp.text){ text=resp.text.substring(0,22000); basis='fulltext'; } } catch(e){} }
  if (!text){ text=(art.abstract||'').toString(); basis='abstract'; }
  if (!text || text.length<40){ art._meta_status='no_text'; continue; }
  art._meta_basis=basis;
  const prompt = buildPrompt(art, text);
  let parsed=null, raw='';
  try { const rp=await this.helpers.httpRequest({ method:'POST', url:PROXY+'/api/generate', body:JSON.stringify({ model:'qwen2.5:3b', prompt:prompt, stream:false, format:'json', options:{temperature:0,num_predict:600,num_ctx:32768}, keep_alive:'30m', _ultralab_task:'extraction' }), headers:{'Content-Type':'application/json'}, json:true, timeout:900000 }); raw=(rp&&rp.response)||''; parsed=extractJson(raw); } catch(e){}
  if (!parsed || parsed.data_type==='none' || !parsed.data_type){ art._meta_status='no_data'; art._meta_raw=raw.substring(0,150); continue; }
  art._meta_data=parsed; art._meta_status='extracted';
  studies.push(art);
}

// mesure auto = inferee du 1er study exploitable
if (MEASURE==='AUTO'){
  const first = studies.find(function(s){ const t=s._meta_data.data_type; return t==='binary'||t==='continuous'||t==='precomputed'||t==='proportion'; });
  if (first){ const t=first._meta_data.data_type; const em=(first._meta_data.effect_measure||'').toUpperCase(); MEASURE = (t==='binary')?'OR':(t==='continuous')?'SMD':(t==='proportion')?'PFT':(em||'OR'); }
  else MEASURE='OR';
}
const isLog = !!LOGM[MEASURE];

// ---- 2. Derivation des effets ----
const eff = [];
for (const s of studies){
  const md = s._meta_data;
  const dz = String(md.design||'').toLowerCase();
  // LOT-A F6a : controle partage (multi-bras) - division du bras controle posee par l'humain (set-uoa)
  var d2 = md;
  var uoaArms = num(md._uoa_shared_control_arms);
  if (uoaArms && uoaArms > 1){
    d2 = Object.assign({}, md, {
      n_control: md.n_control!=null ? num(md.n_control)/uoaArms : md.n_control,
      events_control: md.events_control!=null ? num(md.events_control)/uoaArms : md.events_control
    });
    s._meta_uoa = 'shared_control_divided';
  }
  // LOT-A F6c : cross-over sans effet apparie -> exclu (les donnees brutes ignorent l'appariement)
  if ((dz.indexOf('crossover')>=0 || dz.indexOf('cross-over')>=0)
      && !(md.effect!=null && md.ci_lower!=null && md.ci_upper!=null)){
    s._meta_included=false; s._meta_status='crossover_unpaired'; continue;
  }
  const e = deriveEffect(d2, MEASURE);
  // J6 : double zero -> hors poolage, mais compte et trace (isFinite(null) vaut true,
  // ce test doit donc rester AVANT le test generique ci-dessous).
  if (e && e.exclude==='double_zero'){
    s._meta_included=false; s._meta_status='double_zero';
    s._meta_note='aucun evenement dans les deux bras : etude sans information sur le rapport, exclue du poolage (Cochrane Handbook 10.4.4.1)';
    continue;
  }
  if (e && isFinite(e.yi) && isFinite(e.vi) && e.vi>0){
    var uoaVi = e.vi;
    // LOT-A F6b : essai en grappes - inflation de variance par l'effet de design (pose par set-uoa)
    var uoaDe = num(md._uoa_design_effect) || num(md.design_effect);
    if (uoaDe && uoaDe > 1){ uoaVi = uoaVi*uoaDe; s._meta_uoa = 'cluster_DE_' + uoaDe; }
    s._meta_yi=e.yi; s._meta_vi=uoaVi; s._meta_se=Math.sqrt(uoaVi); s._meta_included=true;
    if (e.cc){ s._meta_zero_cc=true; }
    eff.push(s);
  } else { s._meta_included=false; s._meta_status='incompatible'; }
}

const summary = { outcome: OUTCOME, measure: MEASURE, is_log: isLog, k: eff.length, n_excluded: studies.length-eff.length, total: articles.length };
// LOT-A F6 : bilan des corrections d'unite d'analyse (consomme par sof_table + UI)
summary.uoa = {
  n_shared_control: eff.filter(function(s){return s._meta_uoa==='shared_control_divided';}).length,
  n_cluster_adjusted: eff.filter(function(s){return String(s._meta_uoa||'').indexOf('cluster_DE_')===0;}).length,
  n_crossover_excluded: studies.filter(function(s){return s._meta_status==='crossover_unpaired';}).length,
  corrections_applied: eff.some(function(s){return !!s._meta_uoa;}) || studies.some(function(s){return s._meta_status==='crossover_unpaired';})
};
// J6 : bilan des cellules a zero - le rapport doit pouvoir nommer la convention appliquee.
summary.zero_cells = {
  n_double_zero_excluded: studies.filter(function(s){return s._meta_status==='double_zero';}).length,
  n_continuity_corrected: eff.filter(function(s){return !!s._meta_zero_cc;}).length,
  method: ZERO_METHOD
};

if (eff.length >= 2){
  // ---- 3. Pooling ----
  let sumW=0,sumWy=0,sumW2=0;
  for (const s of eff){ const w=1/s._meta_vi; sumW+=w; sumWy+=w*s._meta_yi; sumW2+=w*w; }
  const ybarF=sumWy/sumW;
  let Q=0; for (const s of eff){ Q+=(1/s._meta_vi)*Math.pow(s._meta_yi-ybarF,2); }
  const df=eff.length-1;
  const C=sumW-sumW2/sumW;
  const tau2=(C>0)?Math.max(0,(Q-df)/C):0;
  const I2=(Q>df && Q>0)?Math.max(0,(Q-df)/Q)*100:0;
  let sumWs=0,sumWsy=0; for (const s of eff){ const ws=1/(s._meta_vi+tau2); sumWs+=ws; sumWsy+=ws*s._meta_yi; s._meta_wstar=ws; }
  const ybarR=sumWsy/sumWs; const varR=1/sumWs; const seR=Math.sqrt(varR);
  for (const s of eff){ s._meta_weight=Math.round(s._meta_wstar/sumWs*1000)/10; }
  // J2 : IC du modele aleatoire. Par DEFAUT quantile normal 1,96 (chiffres historiques
  // strictement inchanges) ; l ajustement HKSJ ne s applique que s il est DEMANDE et applicable.
  const hk=hksjStats(eff.map(function(s){return s._meta_yi;}), eff.map(function(s){return s._meta_wstar;}), sumWs, ybarR);
  const useHK=HKSJ && hk.available;
  const ciHalf=useHK?(hk.t*hk.se):(1.96*seR);
  const ciRl=ybarR-ciHalf, ciRh=ybarR+ciHalf;
  const varF=1/sumW, seF=Math.sqrt(varF);
  // J1 : intervalle de PREDICTION = Higgins, Thompson & Spiegelhalter -> quantile de
  // STUDENT a k-2 ddl (et non 1,96). Avec k<3 le ddl n existe pas : PAS d intervalle
  // (on renvoie l absence explicite plutot qu un intervalle bidon).
  const dfPI=eff.length-2;
  const tPI=tQuantile975(dfPI);
  const piL=(tPI!=null)?(ybarR-tPI*Math.sqrt(tau2+varR)):null;
  const piH=(tPI!=null)?(ybarR+tPI*Math.sqrt(tau2+varR)):null;
  // Egger (k>=3)
  let egger=null;
  if (eff.length>=3){
    const xs=eff.map(function(s){return 1/s._meta_se;}); const ys=eff.map(function(s){return s._meta_yi/s._meta_se;});
    const n=xs.length; const mx=xs.reduce(function(a,b){return a+b;},0)/n, my=ys.reduce(function(a,b){return a+b;},0)/n;
    let sxx=0,sxy=0; for(let i=0;i<n;i++){ sxx+=(xs[i]-mx)*(xs[i]-mx); sxy+=(xs[i]-mx)*(ys[i]-my); }
